mapper.select:
SELECT r.id, r.order_id, r.user_id, r.amount, r.reason, r.kind, r.status, r.prev_status, r.applied_at, r.reviewed_at, r.reviewer_id, r.review_remark, r.return_tracking_no, r.return_shipped_at, r.received_at FROM order_refund r JOIN ( SELECT order_id, MAX(id) AS max_id FROM order_refund WHERE order_id IN
#{orderId}
GROUP BY order_id ) latest ON latest.max_id = r.id

mapper.update:
UPDATE order_refund
SET status = 'COMPLETED', received_at = NOW(3), reviewer_id = #{reviewerId}
WHERE id = #{id} AND status = 'RETURN_SHIPPED' AND kind = 'RETURN'
